// A notification service: per-user, per-channel preferences gate which
// channels an ordinary message may use, an urgent message bypasses that
// gating entirely, and channels are tried in priority order, stopping at
// the first one that genuinely confirms delivery.
class NotificationService {
    private final Map<String, Map<String, Boolean>> preferences = new HashMap<>();

    void setPreference(String userId, String channel, boolean optedIn) {
        preferences.computeIfAbsent(userId, k -> new HashMap<>()).put(channel, optedIn);
    }

    String send(String userId, String message, List<String> priorityChannels, boolean urgent, Map<String, Boolean> simulatedAck) {
        List<String> allowed = new ArrayList<>();
        Map<String, Boolean> userPrefs = preferences.getOrDefault(userId, new HashMap<>());
        for (String channel : priorityChannels) {
            boolean optedIn = userPrefs.getOrDefault(channel, false);
            if (urgent || optedIn) {
                allowed.add(channel);
            }
        }

        if (allowed.isEmpty()) {
            return "\"" + message + "\": SUPPRESSED (no channels allowed by preference, message was not urgent)";
        }

        for (String channel : allowed) {
            if (Boolean.TRUE.equals(simulatedAck.get(channel))) {
                return "\"" + message + "\": DELIVERED via " + channel;
            }
        }

        return "\"" + message + "\": UNDELIVERED (no channel among " + allowed + " confirmed delivery)";
    }
}

