class NotificationService:
    # A notification service: per-user, per-channel preferences gate which
    # channels an ordinary message may use, an urgent message bypasses that
    # gating entirely, and channels are tried in priority order, stopping at
    # the first one that genuinely confirms delivery.
    def __init__(self):
        self.preferences = {}  # userId -> {channel: optedIn}

    def set_preference(self, user_id, channel, opted_in):
        self.preferences.setdefault(user_id, {})[channel] = opted_in

    def send(self, user_id, message, priority_channels, urgent, simulated_ack):
        user_prefs = self.preferences.get(user_id, {})
        allowed = [
            channel for channel in priority_channels
            if urgent or user_prefs.get(channel, False)
        ]

        if not allowed:
            return f'"{message}": SUPPRESSED (no channels allowed by preference, message was not urgent)'

        for channel in allowed:
            if simulated_ack.get(channel):
                return f'"{message}": DELIVERED via {channel}'

        return f'"{message}": UNDELIVERED (no channel among {allowed} confirmed delivery)'


def main():
