    service.set_preference("alice", "push", True)
    service.set_preference("alice", "sms", True)
    service.set_preference("alice", "email", False)

    priority = ["push", "sms", "email"]

    # Notification 1: not urgent, push fails to confirm, falls through to sms
    ack1 = {"push": False, "sms": True, "email": True}
    print(service.send("alice", "Your order shipped", priority, False, ack1))

    # Notification 2: urgent, bypasses alice's own email opt-out, push and sms fail, email confirms
    ack2 = {"push": False, "sms": False, "email": True}
