#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <unordered_map>
using namespace std;

// A notification service: per-user, per-channel preferences gate which
// channels an ordinary message may use, an urgent message bypasses that
// gating entirely, and channels are tried in priority order, stopping at
// the first one that genuinely confirms delivery.
class NotificationService {
public:
    void setPreference(const string& userId, const string& channel, bool optedIn) {
        preferences[userId][channel] = optedIn;
    }

    string send(const string& userId, const string& message, const vector<string>& priorityChannels,
                bool urgent, const map<string, bool>& simulatedAck) {
        vector<string> allowed;
        auto userPrefsIt = preferences.find(userId);
        for (const auto& channel : priorityChannels) {
            bool optedIn = false;
            if (userPrefsIt != preferences.end()) {
                auto chIt = userPrefsIt->second.find(channel);
                if (chIt != userPrefsIt->second.end()) optedIn = chIt->second;
            }
            if (urgent || optedIn) {
                allowed.push_back(channel);
            }
        }

        if (allowed.empty()) {
            return "\"" + message + "\": SUPPRESSED (no channels allowed by preference, message was not urgent)";
        }

        for (const auto& channel : allowed) {
            auto ackIt = simulatedAck.find(channel);
            if (ackIt != simulatedAck.end() && ackIt->second) {
                return "\"" + message + "\": DELIVERED via " + channel;
            }
        }

        return "\"" + message + "\": UNDELIVERED (no channel among " + joinChannels(allowed) + " confirmed delivery)";
    }

private:
    unordered_map<string, unordered_map<string, bool>> preferences;

    static string joinChannels(const vector<string>& channels) {
        string result = "[";
        for (size_t i = 0; i < channels.size(); i++) {
            result += channels[i];
            if (i + 1 < channels.size()) result += ", ";
        }
        result += "]";
        return result;
    }
};

int main() {
    NotificationService service;
    service.setPreference("alice", "push", true);
    service.setPreference("alice", "sms", true);
    service.setPreference("alice", "email", false);

    vector<string> priority = {"push", "sms", "email"};

    // Notification 1: not urgent, push fails to confirm, falls through to sms
    map<string, bool> ack1 = {{"push", false}, {"sms", true}, {"email", true}};
    cout << service.send("alice", "Your order shipped", priority, false, ack1) << endl;

    // Notification 2: urgent, bypasses alice's own email opt-out, push and sms fail, email confirms
    map<string, bool> ack2 = {{"push", false}, {"sms", false}, {"email", true}};
    cout << service.send("alice", "Security alert: new login", priority, true, ack2) << endl;

    // Notification 3: not urgent, only email offered, but alice has opted out and it is not urgent
    map<string, bool> ack3 = {{"email", true}};
    cout << service.send("alice", "Weekly newsletter", {"email"}, false, ack3) << endl;

    return 0;
}

